import { GameEngine } from './gameEngine.js';
const g = new GameEngine\('test', 1, 2\);
g.placeBombs\(1, [0, 1, 2]\);
g.placeBombs\(2, [3, 4, 5]\);
console.log\('phase:', g.phase\);
// Player 1 attacks player 2's board. Player 2 has bombs at 3,4,5
let turn = g.turn;
for \(let i = 0; i < 12; i++\) {
  const cell = i;
  const opponentId = Object.keys\(g.players\).map\(Number\).find\(id => id !== turn\);
  const opponent = g.players[opponentId];
  if \(opponent.revealed.has\(cell\)\) continue;
  const result = g.makeMove\(turn, cell\);
  console.log\('turn:', turn, 'cell:', cell, 'bomb:', result.bomb, 'lives:', result.livesLeft, 'winner:', result.winner, 'next:', result.nextTurn\);
  if \(result.winner\) break;
  turn = result.nextTurn;
}
console.log\('final phase:', g.phase\);
")
